package com.digitalbase.ticketing.controller;import com.digitalbase.ticketing.dto.ProductPlanRequest;import com.digitalbase.ticketing.dto.ProductPlanResponse;import com.digitalbase.ticketing.service.ProductPlanService;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController@RequestMapping("/api/admin/product-plans")@RequiredArgsConstructorpublic class ProductPlanController {    private final ProductPlanService productPlanService;    @PostMapping    public ResponseEntity<ProductPlanResponse> createPlan(@RequestBody ProductPlanRequest request) {        return new ResponseEntity<>(productPlanService.createProductPlan(request), HttpStatus.CREATED);    }    @GetMapping    public ResponseEntity<List<ProductPlanResponse>> getAllPlans() {        return ResponseEntity.ok(productPlanService.getAllProductPlans());    }    @GetMapping("/product/{productId}")    public ResponseEntity<List<ProductPlanResponse>> getPlansByProductId(@PathVariable Long productId) {        return ResponseEntity.ok(productPlanService.getProductPlansByProductId(productId));    }    @GetMapping("/{id}")    public ResponseEntity<ProductPlanResponse> getPlanById(@PathVariable Long id) {        return ResponseEntity.ok(productPlanService.getProductPlanById(id));    }    @PutMapping("/{id}")    public ResponseEntity<ProductPlanResponse> updatePlan(@PathVariable Long id, @RequestBody ProductPlanRequest request) {        return ResponseEntity.ok(productPlanService.updateProductPlan(id, request));    }    @DeleteMapping("/{id}")    public ResponseEntity<String> deletePlan(@PathVariable Long id) {        productPlanService.deleteProductPlan(id);        return ResponseEntity.ok("Product Plan deleted successfully.");    }}